"""id — sira_c."""

T = {
"sira_151": ("Paman Nabi ﷺ yang manakah masuk Islam dan menjadi salah satu pembelanya yang paling teguh di Makkah?", ["Hamzah bin Abdul Muttalib", "Abu Lahab", "Abu Thalib", "Al-Abbas"], "Hamzah, paman sekaligus saudara sepersusuan Nabi ﷺ, masuk Islam di Makkah dan dijuluki «singa Allah»."),
"sira_152": ("Di rumah siapa kaum muslimin pertama berkumpul diam-diam di Makkah?", ["Di rumah al-Arqam", "Di rumah Abu Bakar", "Di rumah Khadijah", "Di rumah Abu Thalib"], "Rumah al-Arqam bin Abil-Arqam di bukit Safa menjadi tempat berkumpul dan belajar yang pertama."),
"sira_153": ("Sahabat manakah, yang masuk Islam di Makkah, kemudian diutus sebagai guru pertama ke Yatsrib?", ["Mus'ab bin Umair", "Bilal bin Rabah", "Khalid bin Walid", "Abu Hurairah"], "Mus'ab bin Umair, pemuda Makkah dari keluarga terpandang, diutus ke Yatsrib setelah baiat Aqabah untuk mengajarkan Al-Qur'an."),
"sira_154": ("Dengan perintah apa surah Al-Muddatstsir, yang memulai dakwah terbuka, dibuka?", ["«Wahai orang yang berselimut! Bangunlah, lalu berilah peringatan»", "«Bacalah dengan nama Tuhanmu»", "«Perangilah orang kafir»", "«Berhijrahlah ke Madinah»"], "«Wahai orang yang berselimut! Bangunlah, lalu berilah peringatan»."),
"sira_155": ("Ayat manakah yang memerintahkan Nabi ﷺ menyampaikan secara terang-terangan apa yang diperintahkan kepadanya?", ["«Maka sampaikanlah secara terang-terangan apa yang diperintahkan kepadamu»", "«Bersabarlah»", "«Bacalah diam-diam»", "«Menyingkirlah»"], "«Maka sampaikanlah secara terang-terangan apa yang diperintahkan kepadamu dan berpalinglah dari orang musyrik»."),
"sira_156": ("Di mana Quraisy menggantung dokumen pemboikotan terhadap Bani Hasyim?", ["Di dalam Ka'bah", "Di pintu kota", "Di pasar Ukazh", "Di bukit Safa"], "Naskah pemboikotan digantung di dalam Ka'bah, sampai perjanjian itu dibatalkan dan dokumennya ditinggalkan."),
"sira_157": ("Di kebun siapa di Thaif Nabi ﷺ berlindung dan menerima setangkai anggur setelah diusir?", ["Di kebun Utbah dan Syaibah, tempat budak Addas melayaninya", "Di rumah pemuka Thaif", "Di kafilah yang lewat", "Di rumah seorang pandai besi"], "Terluka dan diusir dari Thaif, beliau berlindung di sebuah kebun; di sana disuguhkan anggur oleh seorang budak Nasrani bernama Addas."),
"sira_158": ("Sahabat manakah yang semula penentang keras lalu masuk Islam dan dijuluki «pembeda antara yang benar dan yang batil»?", ["Umar bin Khattab", "Abu Sufyan", "Khalid bin Walid", "Amr bin Ash"], "Umar bin Khattab, mula-mula memusuhi, masuk Islam di Makkah dan mendapat gelar al-Faruq."),
"sira_159": ("Di rumah keluarga siapa Nabi ﷺ tinggal saat tiba di Madinah, tempat untanya berhenti?", ["Abu Ayyub al-Anshari", "Sa'd bin Muadz", "Ubay bin Ka'b", "Anas bin Malik"], "Unta itu berhenti di dekat rumah Abu Ayyub al-Anshari, yang menjamu Nabi ﷺ saat kedatangannya."),
"sira_160": ("Apa nama pemakaman Madinah tempat banyak sahabat dimakamkan?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hijr", "Quba"], "Baqi' al-Gharqad di samping Masjid Nabi ﷺ adalah pemakaman kota Madinah."),
"sira_161": ("Masjid manakah yang Al-Qur'an sebut «didirikan atas dasar takwa sejak hari pertama»?", ["Masjid Quba", "Masjidil Haram", "Masjid Al-Aqsa", "Masjid Kufah"], "«Sungguh, masjid yang didirikan atas dasar takwa sejak hari pertama adalah lebih pantas engkau melaksanakan salat di dalamnya»."),
"sira_162": ("Di masjid manakah Nabi ﷺ salat ketika turun perintah memindahkan kiblat?", ["Masjid dua kiblat (Masjid Qiblatain)", "Masjid Quba", "Masjidil Haram", "Masjid Al-Aqsa"], "Perintah itu turun di tengah salat; para jamaah berbalik menghadap Ka'bah, karena itu disebut «masjid dua kiblat»."),
"sira_163": ("Kewajiban apa yang disyariatkan bagi kaum muslimin pada tahun kedua Hijriah?", ["Puasa bulan Ramadan", "Haji", "Salat malam", "Perjalanan ke Thaif"], "Puasa Ramadan diwajibkan di Madinah pada tahun kedua Hijriah."),
"sira_164": ("Sahabat manakah yang melihat lafaz azan dalam mimpi, lalu diadopsi oleh Nabi ﷺ?", ["Abdullah bin Zaid", "Bilal bin Rabah", "Abu Bakar", "Muadz bin Jabal"], "Abdullah bin Zaid menceritakan mimpi azan; Nabi ﷺ menyetujuinya dan menyuruh Bilal mengumandangkannya."),
"sira_165": ("Apa yang Al-Qur'an katakan tentang segenggam tanah yang Nabi ﷺ lempar di Badar?", ["«Bukan engkau yang melempar ketika engkau melempar, tetapi Allah yang melempar»", "«Bidikanmu tepat»", "«Angin yang membawanya»", "«Malaikat yang melemparkannya»"], "«Dan bukan engkau yang melempar ketika engkau melempar, tetapi Allah yang melempar»."),
"sira_166": ("Bagaimana Al-Qur'an menggambarkan keadaan sebagian orang beriman saat berangkat ke Badar?", ["Mereka membantahnya seolah digiring menuju kematian", "Semuanya bersemangat", "Mereka menolak berangkat", "Mereka meminta penundaan"], "«Mereka membantahmu tentang kebenaran setelah nyata, seolah-olah mereka dihalau kepada kematian»."),
"sira_167": ("Bagaimana Al-Qur'an mengingatkan orang beriman tentang keadaan mereka sebelum kemenangan?", ["Mereka sedikit dan tertindas di bumi, lalu Allah memberi tempat dan pertolongan", "Mereka kaya", "Mereka banyak", "Mereka sudah berkuasa"], "«Dan ingatlah ketika kamu masih sedikit lagi tertindas di bumi… lalu Dia memberimu tempat menetap dan memperkuatmu dengan pertolongan-Nya»."),
"sira_168": ("Sahabat manakah di Badar yang mengusulkan memindahkan pasukan ke sumur terdekat dengan musuh?", ["Al-Hubab bin al-Mundzir", "Sa'd bin Muadz", "Al-Miqdad", "Az-Zubair"], "Al-Hubab bin al-Mundzir bertanya apakah posisi itu wahyu atau pendapat; setelah tahu itu pendapat, dia mengusulkan maju ke sumur, dan Nabi ﷺ menerimanya."),
"sira_169": ("Apa nama mata air tempat perang Badar terjadi?", ["Badar, sumur di jalur kafilah", "Zamzam", "Quba", "Hudaibiyah"], "Badar adalah sumber air di jalur kafilah antara Makkah dan Syam; perang itu dinamai dengannya."),
"sira_170": ("Perkara apa tentang tawanan yang dibahas melalui wahyu setelah Badar?", ["Tebusan yang diterima bagi para tawanan", "Pembagian air", "Pemilihan tempat berkemah", "Tanggal kepulangan"], "Bagian itu membahas tawanan dan tebusan, lalu menghalalkan apa yang telah diambil sebagai rezeki yang halal dan baik."),
"sira_171": ("Menurut surah Ali 'Imran, apa yang membalikkan keadaan di Uhud setelah keberhasilan awal?", ["Ketidaktaatan dan perselisihan tentang perintah yang diterima", "Jumlah musuh", "Panas terik", "Kekurangan air"], "«…hingga kamu lemah dan berselisih tentang urusan itu dan mendurhakai perintah»."),
"sira_172": ("Apa yang Al-Qur'an katakan tentang mereka yang gugur di jalan Allah?", ["Jangan mengira mereka mati: mereka hidup di sisi Tuhannya", "Mereka tidur hingga hari akhir", "Mereka kembali", "Mereka dilupakan"], "«Dan jangan sekali-kali kamu mengira bahwa orang yang gugur di jalan Allah itu mati; sebenarnya mereka hidup di sisi Tuhannya, mendapat rezeki»."),
"sira_173": ("Di bukit manakah Nabi ﷺ menempatkan para pemanah di Uhud?", ["Bukit para pemanah (Jabal ar-Rumat)", "Bukit Safa", "Gunung Tsur", "Gunung Hira"], "Lima puluh pemanah ditempatkan di sebuah bukit yang kemudian disebut «bukit para pemanah», dengan perintah untuk tidak meninggalkannya."),
"sira_174": ("Bagaimana surah Al-Ahzab menggambarkan ujian pengepungan Madinah?", ["Penglihatan terpaku dan hati naik ke tenggorokan", "Kota jatuh", "Hanya bekal yang habis", "Langit menjadi gelap"], "«Ketika mereka datang kepadamu dari atas dan dari bawah, dan ketika penglihatan terpaku dan hati naik ke tenggorokan»."),
"sira_175": ("Bagaimana Al-Qur'an menggambarkan akhir perang Khandaq?", ["Allah memukul mundur pasukan sekutu dengan kemarahan mereka tanpa memperoleh kebaikan", "Pertempuran panjang", "Sebuah perjanjian damai", "Mundurnya kaum muslimin"], "«Dan Allah menghalau orang-orang kafir itu dalam keadaan penuh kemarahan: mereka tidak memperoleh keuntungan apa pun, dan Allah cukup bagi orang beriman dalam peperangan»."),
"sira_176": ("Di manakah Hudaibiyah, tempat perjanjian yang masyhur itu?", ["Di batas tanah haram, sebelah barat Makkah", "Dekat Madinah", "Di Yaman", "Di Syam"], "Hudaibiyah adalah tempat di batas tanah haram Makkah; di sanalah perjanjian itu dibuat."),
"sira_177": ("Mimpi Nabi ﷺ manakah yang Al-Qur'an benarkan setelah Hudaibiyah?", ["Bahwa mereka akan memasuki Masjidil Haram dengan aman, dengan kepala dicukur atau digunting", "Bahwa mereka akan menang di Khaibar", "Bahwa mereka akan membangun kota", "Bahwa mereka akan pergi ke Syam"], "«Sungguh, Allah akan membuktikan kepada Rasul-Nya kebenaran mimpinya: kamu pasti akan memasuki Masjidil Haram dengan aman»."),
"sira_178": ("Apa yang surah Al-Fath ingatkan tentang tangan-tangan yang ditahan di Makkah?", ["Allah menahan tangan mereka dari kamu dan tanganmu dari mereka di tengah kota Makkah", "Dia memerintahkan berperang", "Dia menutup jalan", "Dia mengirim badai"], "«Dan Dialah yang menahan tangan mereka dari kamu dan tanganmu dari mereka di tengah kota Makkah, setelah Dia memenangkan kamu atas mereka»."),
"sira_179": ("Pada tahun Hijriah keberapa ekspedisi Khaibar terjadi?", ["Ketujuh", "Kedua", "Kelima", "Kesepuluh"], "Khaibar terjadi pada tahun 7 Hijriah, setahun setelah perjanjian Hudaibiyah."),
"sira_180": ("Apa nama umrah yang dilaksanakan setahun setelah Hudaibiyah, sesuai isi perjanjian?", ["Umratul-Qadha", "Haji Wada'", "Umrah Ji'ranah", "Haji Akbar"], "Perjanjian itu menetapkan kaum muslimin kembali tahun berikutnya; umrah itu disebut umratul-qadha."),
"sira_181": ("Penguasa manakah yang merobek surat Nabi ﷺ ketika menerimanya?", ["Raja Persia (Kisra)", "Najasyi Habasyah", "Gubernur Bahrain", "Raja Yaman"], "Nabi ﷺ mengirim surat kepada para penguasa tetangga; surat kepada raja Persia dirobek."),
"sira_182": ("Sahabat manakah yang membawa surat Nabi ﷺ kepada Najasyi Habasyah dan penguasa lain?", ["Amr bin Umayyah ad-Dhamri", "Abu Hurairah", "Anas bin Malik", "Ubay bin Ka'b"], "Para utusan dipilih dari kalangan sahabat; Amr bin Umayyah ad-Dhamri diutus kepada Najasyi."),
"sira_183": ("Ke arah manakah letak Khaibar dari Madinah?", ["Ke utara", "Ke selatan", "Ke timur", "Ke barat, di tepi laut"], "Khaibar adalah oase berbenteng di utara Madinah, di jalur menuju Syam."),
"sira_184": ("Menjadi apa rumah Abu Sufyan pada hari penaklukan Makkah?", ["Tempat aman bagi siapa pun yang memasukinya", "Sebuah penjara", "Sebuah gudang", "Sebuah masjid"], "Nabi ﷺ mengumumkan keamanan bagi siapa pun yang masuk Masjidil Haram, tinggal di rumahnya, atau masuk ke rumah Abu Sufyan."),
"sira_185": ("Tahun manakah yang disebut «tahun penaklukan» ('am al-fath)?", ["Tahun 8 Hijriah", "Tahun 6 Hijriah", "Tahun 10 Hijriah", "Tahun 2 Hijriah"], "Makkah ditaklukkan pada tahun 8 Hijriah, tahun yang dikenal sebagai tahun penaklukan."),
"sira_186": ("Perang manakah yang terjadi tak lama setelah penaklukan Makkah, melawan kabilah Hawazin?", ["Hunain", "Badar", "Uhud", "Khaibar"], "Hunain terjadi tak lama setelah penaklukan, di sebuah lembah antara Makkah dan Thaif."),
"sira_187": ("Apa yang Allah turunkan kepada Rasul-Nya ﷺ dan orang beriman setelah kegoncangan mereka di Hunain?", ["Ketenangan-Nya (sakinah) dan bala tentara yang tidak mereka lihat", "Hujan", "Angin", "Bala bantuan penunggang kuda"], "«Kemudian Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang-orang beriman, dan Dia menurunkan bala tentara yang tidak kamu lihat»."),
"sira_188": ("Ke kota manakah pasukan muslim bergerak setelah Hunain?", ["Thaif", "Khaibar", "Tabuk", "Sana'a"], "Setelah Hunain kaum muslimin mengepung Thaif, yang penduduknya berlindung di dalam benteng."),
"sira_189": ("Ekspedisi manakah yang Al-Qur'an sebut «saat kesulitan» (sa'atul-'usrah)?", ["Tabuk", "Badar", "Khaibar", "Hunain"], "«Sungguh, Allah telah menerima tobat Nabi, orang-orang Muhajirin dan Anshar yang mengikutinya pada saat kesulitan»."),
"sira_190": ("Apa yang Al-Qur'an katakan tentang tiga sahabat yang tertinggal di Tabuk, sebelum mereka diampuni?", ["Bumi terasa sempit bagi mereka padahal luas, lalu Allah menerima tobat mereka", "Mereka diusir", "Mereka pergi ke Yaman", "Mereka dilupakan"], "«Dan terhadap tiga orang yang ditinggalkan: hingga bumi terasa sempit bagi mereka padahal bumi itu luas… kemudian Allah menerima tobat mereka»."),
"sira_191": ("Ke arah manakah letak Tabuk, tujuan ekspedisi besar terakhir?", ["Ke utara, menuju perbatasan Syam", "Ke selatan, menuju Yaman", "Ke timur, menuju Irak", "Ke barat, di Laut Merah"], "Tabuk berada di utara Madinah, di jalur menuju Syam; itulah ekspedisi besar terakhir Nabi ﷺ."),
"sira_192": ("Sahabat manakah yang membiayai sebagian besar pasukan Tabuk dari hartanya sendiri?", ["Utsman bin Affan", "Sa'd bin Abi Waqqas", "Thalhah bin Ubaidillah", "Abu Dzar"], "Utsman bin Affan menyediakan bagian besar perlengkapan «pasukan kesulitan» (jaisyul-'usrah)."),
"sira_193": ("Sahabat manakah yang pertama melepaskan anak panah di jalan Allah?", ["Sa'd bin Abi Waqqas", "Az-Zubair bin al-Awwam", "Thalhah bin Ubaidillah", "Abu Ubaidah"], "Sa'd bin Abi Waqqas, termasuk yang paling awal masuk Islam, dikenal sebagai orang pertama yang melepaskan anak panah di jalan Allah."),
"sira_194": ("Sahabat manakah yang disebut «hawari Rasulullah ﷺ»?", ["Az-Zubair bin al-Awwam", "Abu Hurairah", "Salman al-Farisi", "Bilal"], "Az-Zubair bin al-Awwam, sepupu Nabi ﷺ, disebut hawari beliau, penolong terdekatnya."),
"sira_195": ("Sahabat manakah yang dipercayai pengetahuan tentang kaum munafik sehingga disebut «pemegang rahasia»?", ["Hudzaifah bin al-Yaman", "Abu Musa al-Asy'ari", "Ammar bin Yasir", "Abud-Darda"], "Hudzaifah bin al-Yaman dikenal sebagai «shahibus-sirr», orang yang Nabi ﷺ percayai tentang kaum munafik."),
"sira_196": ("Dari negeri manakah Salman, yang dijuluki «al-Farisi», pengusul parit?", ["Dari Persia", "Dari Yaman", "Dari Habasyah", "Dari Romawi"], "Salman berasal dari Persia; ia lama mencari kebenaran sebelum bergabung dengan Nabi ﷺ di Madinah."),
"sira_197": ("Perempuan manakah, ibu Anas bin Malik, yang menyerahkan pelayanan putranya kepada Nabi ﷺ?", ["Ummu Sulaim", "Ummu Salamah", "Ummu Aiman", "Ummu Habibah"], "Ummu Sulaim dari kaum Anshar menyerahkan putranya Anas untuk melayani Nabi ﷺ saat beliau tiba di Madinah."),
"sira_198": ("Istri Nabi ﷺ manakah yang dikenal luas ilmunya dan meriwayatkan banyak hadis?", ["Aisyah", "Saudah", "Juwairiyah", "Maimunah"], "Aisyah, putri Abu Bakar, termasuk periwayat hadis terbesar dan rujukan dalam ilmu agama."),
"sira_199": ("Istri Nabi ﷺ manakah yang merupakan sepupunya dan pernikahannya disebut dalam surah Al-Ahzab?", ["Zainab binti Jahsy", "Hafshah", "Ummu Salamah", "Shafiyah"], "Pernikahan dengan Zainab binti Jahsy disebut dalam surah Al-Ahzab (33:37)."),
"sira_200": ("Istri Nabi ﷺ manakah yang memberi saran yang memecahkan kebuntuan Hudaibiyah?", ["Ummu Salamah", "Aisyah", "Hafshah", "Zainab binti Jahsy"], "Ummu Salamah menyarankan Nabi ﷺ keluar dan sendiri menyembelih kurban serta bercukur; para sahabat pun segera mengikutinya."),
"sira_201": ("Apa nama lengkap Nabi ﷺ sampai kakeknya?", ["Muhammad bin Abdullah bin Abdul Muttalib", "Muhammad bin Abi Thalib", "Muhammad bin al-Abbas", "Muhammad bin Hasyim"], "Beliau adalah Muhammad bin Abdullah bin Abdul Muttalib, dari suku Quraisy."),
"sira_202": ("Nama lain Nabi ﷺ yang disebut Isa dalam Al-Qur'an, yang berarti «yang paling terpuji», adalah?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abul-Qasim"], "Isa mengabarkan seorang rasul sesudahnya «yang namanya Ahmad» (Al-Qur'an 61:6)."),
"sira_203": ("Berapa lama Al-Qur'an diturunkan kepada Nabi ﷺ?", ["Sekitar dua puluh tiga tahun", "Sepuluh tahun", "Empat puluh tahun", "Satu malam saja"], "Wahyu berlangsung sekitar dua puluh tiga tahun: tiga belas tahun di Makkah dan sepuluh tahun di Madinah."),
"sira_204": ("Sahabat manakah yang menjadi lelaki merdeka dewasa pertama yang masuk Islam?", ["Abu Bakar ash-Shiddiq", "Umar bin Khattab", "Utsman bin Affan", "Sa'd bin Abi Waqqas"], "Di antara lelaki merdeka dewasa, Abu Bakar adalah yang pertama menyambut seruan Nabi ﷺ."),
"sira_205": ("Anak manakah yang pertama masuk Islam?", ["Ali bin Abi Thalib", "Anas bin Malik", "Usamah bin Zaid", "Abdullah bin Umar"], "Ali bin Abi Thalib, yang dibesarkan di rumah Nabi ﷺ, adalah anak pertama yang beriman."),
"sira_206": ("Bekas budak Nabi ﷺ manakah yang pertama masuk Islam di antara para maula?", ["Zaid bin Haritsah", "Bilal bin Rabah", "Shuhaib ar-Rumi", "Salman al-Farisi"], "Zaid bin Haritsah, yang dimerdekakan dan diasuh seperti anak oleh Nabi ﷺ, adalah maula pertama yang beriman."),
"sira_207": ("Ayat manakah yang mengakhiri pengangkatan anak secara hukum dengan menyatakan Nabi ﷺ bukan ayah dari salah seorang lelaki mereka?", ["«Muhammad bukanlah bapak dari seseorang di antara kamu, tetapi dia adalah utusan Allah dan penutup para nabi»", "«Panggillah mereka dengan nama bapak mereka»", "«Hubungan darah lebih utama»", "«Jangan mengangkat anak»"], "«Muhammad bukanlah bapak dari seseorang di antara kamu, tetapi dia adalah utusan Allah dan penutup para nabi»."),
"sira_208": ("Pada hari apa kaum muslimin berkumpul untuk salat berjamaah yang disyariatkan di Madinah?", ["Jumat", "Sabtu", "Minggu", "Senin"], "Salat Jumat disyariatkan di Madinah dan mengumpulkan umat setiap pekan."),
"sira_209": ("Sahabat manakah yang mengimami salat pada masa sakit terakhir Nabi ﷺ, atas perintah beliau?", ["Abu Bakar ash-Shiddiq", "Umar bin Khattab", "Ali bin Abi Thalib", "Bilal"], "Nabi ﷺ memerintahkan Abu Bakar mengimami salat pada masa sakitnya; para sahabat memandangnya sebagai isyarat."),
"sira_210": ("Khalifah manakah yang ditikam saat mengimami salat subuh?", ["Umar bin Khattab", "Abu Bakar", "Ali bin Abi Thalib", "Muawiyah"], "Umar bin Khattab ditikam saat salat subuh di Madinah dan wafat karena lukanya."),
"sira_211": ("Berapa lama kekhalifahan Abu Bakar?", ["Sekitar dua tahun", "Sepuluh tahun", "Dua puluh tahun", "Tiga puluh tahun"], "Abu Bakar memerintah sekitar dua tahun sebelum wafat, lalu Umar menggantikannya."),
"sira_212": ("Gerakan apa yang harus Abu Bakar hadapi di awal kekhalifahannya?", ["Penolakan zakat dan kemurtadan sebagian kabilah", "Serbuan dari Persia", "Kelaparan", "Pemberontakan di Madinah"], "Kekhalifahan pertama dibuka dengan perang riddah melawan kabilah yang menolak zakat atau meninggalkan Islam."),
"sira_213": ("Gelar apa yang Umar bin Khattab pakai sebagai pemimpin umat?", ["Amirul Mukminin", "Sultan", "Malik", "Imam al-Haramain"], "Gelar amirul mukminin mapan pada masa Umar dan dipakai para khalifah sesudahnya."),
"sira_214": ("Masjid manakah di Baitul Maqdis yang menjadi kiblat pertama kaum muslimin?", ["Masjid Al-Aqsa", "Masjid Quba", "Masjid Nabi ﷺ", "Masjidil Haram"], "Kaum muslimin mula-mula salat menghadap Baitul Maqdis sebelum kiblat ditetapkan ke Ka'bah."),
"sira_215": ("Apa tiga masjid yang secara khusus dianjurkan untuk dikunjungi?", ["Masjidil Haram, Masjid Nabi ﷺ, dan Al-Aqsa", "Quba, Al-Aqsa, dan Kufah", "Masjidil Haram, Quba, dan Damaskus", "Al-Aqsa, Kufah, dan Bashrah"], "Perjalanan dianjurkan secara khusus ke tiga masjid: Masjidil Haram, Masjid Nabi ﷺ, dan Masjid Al-Aqsa."),
"sira_216": ("Di manakah Nabi ﷺ menyampaikan khutbah wada' pada hari Arafah?", ["Di lembah Uranah, di Arafah", "Di Mina", "Di depan Ka'bah", "Di Muzdalifah"], "Khutbah wada' disampaikan pada hari Arafah di lembah Uranah di kaki Jabal Arafah."),
"sira_217": ("Apa yang Nabi ﷺ nyatakan sebagai terlarang dilanggar dalam khutbah wada'?", ["Darah, harta, dan kehormatan setiap orang", "Jalur perdagangan", "Sumur-sumur Madinah", "Kebun-kebun kurma"], "Beliau menyatakan darah, harta, dan kehormatan kaum muslimin haram, sebagaimana haramnya hari itu, bulan itu, dan negeri itu."),
"sira_218": ("Apa yang Nabi ﷺ tinggalkan bagi umatnya menurut khutbah wada', agar tidak tersesat?", ["Kitab Allah", "Sebuah harta", "Sebuah pasukan", "Sebuah peta"], "Beliau mengingatkan bahwa beliau meninggalkan di tengah mereka apa yang bila dipegang teguh mereka tidak akan tersesat: Kitab Allah."),
"sira_219": ("Pada bulan apa dalam kalender Islam haji dilaksanakan, yang Nabi ﷺ tunaikan saat perpisahan?", ["Zulhijah", "Ramadan", "Muharam", "Rajab"], "Haji wada' berlangsung pada Zulhijah tahun 10 Hijriah."),
"sira_220": ("Siapa yang memandikan dan mengafani jasad Nabi ﷺ setelah wafat?", ["Keluarganya, di antaranya Ali dan al-Abbas", "Hanya kaum Anshar", "Bilal dan Anas", "Penduduk Quba"], "Keluarganya sendiri yang menanganinya, di antaranya Ali bin Abi Thalib dan pamannya al-Abbas."),
"sira_221": ("Pada bulan Hijriah apa Nabi ﷺ wafat?", ["Rabiul Awal", "Ramadan", "Syawal", "Zulkaidah"], "Nabi ﷺ wafat di Madinah pada bulan Rabiul Awal tahun 11 Hijriah."),
"sira_222": ("Ayat apa yang Abu Bakar bacakan untuk mengingatkan bahwa Nabi ﷺ adalah manusia yang wafat?", ["«Muhammad hanyalah seorang rasul; sebelumnya telah berlalu beberapa rasul»", "«Kami mengutusmu sebagai rahmat»", "«Sesungguhnya engkau berbudi pekerti yang agung»", "«Apabila datang pertolongan Allah»"], "«Muhammad hanyalah seorang rasul; sebelumnya telah berlalu beberapa rasul. Apakah jika dia wafat atau dibunuh kamu berbalik ke belakang?»"),
"sira_223": ("Sahabat manakah yang terutama dikenal karena banyaknya hadis yang dihafalnya?", ["Abu Hurairah", "Anas bin Malik", "Jabir bin Abdullah", "Abu Sa'id al-Khudri"], "Abu Hurairah menyertai Nabi ﷺ pada tahun-tahun terakhir hidupnya dan menjadi periwayat hadis terbanyak."),
"sira_224": ("Sahabat manakah, sepupu Nabi ﷺ, yang menjadi rujukan besar dalam tafsir Al-Qur'an?", ["Abdullah bin Abbas", "Abdullah bin Umar", "Abdullah bin Mas'ud", "Abdullah bin az-Zubair"], "Abdullah bin Abbas, yang Nabi ﷺ doakan agar paham Kitab, dijuluki «penerjemah Al-Qur'an»."),
"sira_225": ("Sahabat manakah yang Nabi ﷺ utus sebagai gubernur dan hakim ke Yaman, dan wafat muda di Syam?", ["Muadz bin Jabal", "Abu Ubaidah bin al-Jarrah", "Amr bin Ash", "Khalid bin Walid"], "Muadz bin Jabal, seorang alim di kalangan sahabat, diutus ke Yaman lalu wafat di Syam saat masih muda."),
"sira_226": ("Lembah manakah yang terbentang di antara bukit Safa dan Marwah, yang ditempuh saat haji?", ["Lembah Makkah, di sekitar Ka'bah", "Lembah Uranah", "Lembah Mina", "Lembah Badar"], "Safa dan Marwah adalah dua bukit kecil di lembah Makkah, kini termasuk dalam Masjidil Haram."),
"sira_227": ("Dua kabilah Arab besar di Madinah manakah yang saling berperang sebelum kedatangan Nabi ﷺ?", ["Aus dan Khazraj", "Quraisy dan Hawazin", "Tsaqif dan Kinanah", "Tamim dan Bakar"], "Aus dan Khazraj, yang lama bermusuhan, bersama-sama membentuk kaum Anshar setelah kedatangan Nabi ﷺ."),
"sira_228": ("Ayat manakah yang mengingatkan kaum Anshar bahwa mereka dahulu bermusuhan dan Allah menyatukan hati mereka?", ["«Kamu dahulu bermusuhan, lalu Dia mempersatukan hatimu»", "«Kamu dahulu miskin»", "«Kamu dahulu sedikit»", "«Kamu dahulu sesat»"], "«Dan ingatlah nikmat Allah kepadamu ketika kamu dahulu bermusuhan, lalu Allah mempersatukan hatimu, sehingga dengan karunia-Nya kamu menjadi bersaudara»."),
"sira_229": ("Bagaimana Al-Qur'an memuji kaum Anshar dalam menyambut kaum Muhajirin?", ["Mereka mengutamakan orang lain daripada diri sendiri meski mereka sendiri kekurangan", "Mereka menjual tanah kepada mereka", "Mereka meminjamkan uang", "Mereka menempatkan mereka di luar kota"], "«Dan mereka mengutamakan orang lain daripada diri mereka sendiri, meskipun mereka juga memerlukan. Siapa yang dijaga dari kekikiran dirinya, merekalah orang-orang yang beruntung»."),
"sira_230": ("Apa sebutan bagi keseluruhan ucapan, perbuatan, dan persetujuan Nabi ﷺ?", ["Sunnah", "Al-Qur'an", "Sirah", "Tafsir"], "Sunnah adalah apa yang Nabi ﷺ katakan, lakukan, atau setujui; sirah adalah kisah hidup beliau."),
"sira_231": ("Apa sebutan bagi generasi setelah generasi sahabat?", ["Tabiin (para pengikut)", "Anshar", "Muhajirin", "Qurra'"], "Tabiin adalah mereka yang bertemu sahabat tanpa pernah melihat Nabi ﷺ."),
"sira_232": ("Apa sebutan bagi rangkaian perawi sebuah hadis?", ["Sanad (isnad)", "Matan", "Tafsir", "Tajwid"], "Sanad adalah rangkaian perawi; matan adalah teks hadis itu sendiri."),
"sira_233": ("Dua kitab hadis manakah yang dipandang paling ketat dan disebut «dua Sahih»?", ["Sahih al-Bukhari dan Sahih Muslim", "Sunan Abu Dawud dan at-Tirmidzi", "Al-Muwaththa' dan al-Musnad", "Sunan an-Nasa'i dan Ibnu Majah"], "Sahih al-Bukhari dan Sahih Muslim bersama-sama disebut «dua Sahih» (ash-shahihain)."),
"sira_234": ("Di kota manakah Masjid Nabi ﷺ dan makam beliau berada?", ["Madinah", "Makkah", "Baitul Maqdis", "Thaif"], "Masjid Nabi ﷺ dan makam beliau berada di Madinah, kota hijrah."),
"sira_235": ("Julukan apa yang disandang Madinah, terkait cahaya yang dinisbatkan kepadanya?", ["Al-Madinah al-Munawwarah (kota yang bercahaya)", "Ummul Qura", "Darus Salam", "Al-Mada'in"], "Madinah disebut al-Munawwarah; sedangkan Makkah disebut al-Mukarramah."),
"sira_236": ("Nama apa yang Al-Qur'an berikan kepada Makkah sebagai «induk negeri»?", ["Ummul Qura", "Al-Madinah", "Al-Balad al-Amin", "Bakkah"], "«…agar engkau memberi peringatan kepada penduduk Ummul Qura dan orang-orang di sekitarnya»."),
"sira_237": ("Apa pekerjaan Khadijah, istri pertama Nabi ﷺ?", ["Pedagang", "Tabib", "Penyair", "Penenun"], "Khadijah binti Khuwailid adalah pedagang terpandang di Makkah, yang mempercayakan kafilahnya kepada Muhammad ﷺ muda."),
"sira_238": ("Berapa lama Nabi ﷺ beristrikan Khadijah seorang diri?", ["Sampai wafatnya; beliau tidak menikahi wanita lain semasa hidupnya", "Dua tahun", "Lima tahun", "Beliau segera menikah lagi"], "Nabi ﷺ tidak menikahi wanita lain selama Khadijah hidup; pernikahan yang lain terjadi setelah wafatnya."),
"sira_239": ("Siapa nama paman Nabi ﷺ yang melindunginya tanpa masuk Islam?", ["Abu Thalib", "Hamzah", "Al-Abbas", "Abu Lahab"], "Abu Thalib, ayah Ali, melindungi keponakannya dari Quraisy sampai wafatnya."),
"sira_240": ("Paman Nabi ﷺ manakah yang menjadi tawanan di Badar sebelum masuk Islam?", ["Al-Abbas bin Abdul Muttalib", "Abu Thalib", "Hamzah", "Az-Zubair bin Abdul Muttalib"], "Al-Abbas, paman Nabi ﷺ dan leluhur Bani Abbas, ditawan di Badar lalu masuk Islam."),
"sira_241": ("Apa sebutan bagi para sahabat yang ikut perang Badar?", ["Ahli Badar (al-Badriyyun)", "Anshar", "Muhajirin", "Ahli Uhud"], "Para sahabat yang hadir di Badar dikenal sebagai al-Badriyyun, dan keutamaan itu khusus bagi mereka."),
"sira_242": ("Bagian mana dari rampasan yang Al-Qur'an sisihkan untuk Allah, Rasul, kerabat, anak yatim, orang miskin, dan ibnu sabil?", ["Seperlima", "Setengah", "Sepersepuluh", "Sepertiga"], "«Ketahuilah, sesungguhnya apa saja yang kamu peroleh sebagai rampasan perang, maka seperlima untuk Allah, Rasul, kerabat, anak yatim, orang miskin, dan ibnu sabil»."),
"sira_243": ("Ayat manakah, yang dikaitkan dengan khutbah wada', yang melandasi kesetaraan bangsa di sisi Allah?", ["«Yang paling mulia di antara kamu di sisi Allah ialah yang paling bertakwa»", "«Manusia berasal dari satu ayah»", "«Tidak seorang pun memikul beban orang lain»", "«Tidak ada paksaan dalam agama»"], "«Wahai manusia! Sungguh, Kami telah menciptakan kamu dari seorang laki-laki dan seorang perempuan… sesungguhnya yang paling mulia di antara kamu di sisi Allah ialah orang yang paling bertakwa»."),
"sira_244": ("Berapa banyak yang ikut dalam baiat Aqabah kedua, pertemuan menentukan dengan penduduk Yatsrib?", ["Rombongan lebih dari tujuh puluh orang", "Tiga", "Sepuluh", "Lima ratus"], "Baiat Aqabah kedua menghimpun rombongan lebih dari tujuh puluh laki-laki dan perempuan dari Yatsrib."),
"sira_245": ("Berapa naqib (penanggung jawab) yang Nabi ﷺ tetapkan di antara penduduk Yatsrib pada baiat Aqabah?", ["Dua belas", "Empat", "Tujuh", "Dua puluh"], "Dipilih dua belas naqib untuk mewakili kelompok-kelompok rombongan Yatsrib dan menjamin baiat mereka."),
"sira_246": ("Nama apa yang disandang Madinah setelah hijrah?", ["Madinatun Nabi, kota Nabi ﷺ", "Yatsrib", "Hanya Thaibah", "Al-Qura"], "Yatsrib disebut Madinatun Nabi, «kota Nabi ﷺ», disingkat al-Madinah."),
"sira_247": ("Khalifah manakah yang menyalin Al-Qur'an dalam mushaf resmi dan mengirimnya ke berbagai wilayah?", ["Utsman bin Affan", "Abu Bakar", "Umar", "Ali"], "Abu Bakar mengumpulkan teksnya; Utsman menyalin mushaf resmi dan mengirimkannya ke kota-kota besar."),
"sira_248": ("Dengan bahasa apa Al-Qur'an diturunkan kepada Nabi ﷺ?", ["Bahasa Arab", "Bahasa Aram", "Bahasa Persia", "Bahasa Yunani"], "Al-Qur'an diturunkan dengan bahasa Arab yang jelas, bahasa kaum Nabi ﷺ sendiri."),
"sira_249": ("Sahabat manakah yang Nabi ﷺ utus ke Bahrain dan kembali membawa hartanya?", ["Abu Ubaidah bin al-Jarrah", "Bilal", "Anas bin Malik", "Abu Dzar"], "Abu Ubaidah bin al-Jarrah, yang dijuluki «kepercayaan umat ini», kembali dari Bahrain membawa hartanya."),
"sira_250": ("Peristiwa apa yang menandai awal kalender Islam?", ["Hijrah dari Makkah ke Madinah", "Kelahiran Nabi ﷺ", "Wahyu pertama", "Penaklukan Makkah"], "Kalender Hijriah dimulai dari tahun hijrah, keputusan yang diambil pada masa kekhalifahan Umar."),
}
